 private function build_exception_recovery_history( array $history, array $params ): array {
-		$serialized = ConversationSerializer::serialize( $history );
-		$message    = isset( $params['message'] ) ? (string) $params['message'] : '';
+		try {
+			$serialized = ConversationSerializer::serialize( $history );
+		} catch ( \Throwable $e ) {
+			$serialized = array();
+		}
+		$message = isset( $params['message'] ) ? (string) $params['message'] : '';
