+		failureMessage: __(
+			'Unable to retry the durable plan phase.',
+			'superdav-ai-agent'
+		),
+		setsSending: true,
+	},
+	cancel: {
+		path: 'cancel',
+		failureMessage: __(
+			'Unable to cancel the durable plan.',
