+		$request_scheme = strtolower( (string) ( $request_parts['scheme'] ?? '' ) );
+		if ( $request_scheme !== $base_scheme
+			|| (int) ( $request_parts['port'] ?? 0 ) !== (int) ( $base_parts['port'] ?? 0 )
+		) {
