+		}
+
+		$base_path    = '/' . trim( (string) ( $base_parts['path'] ?? '' ), '/' );
+		$request_path = '/' . trim( (string) ( $request_parts['path'] ?? '' ), '/' );
+
+		return $request_path === $base_path || str_starts_with( $request_path, rtrim( $base_path, '/' ) . '/' );

