+		};
+	}
+	if ( result?.applied === false ) {
+		if ( VALIDATION_REASONS.has( result.reason ) ) {
+			return {
+				kind: 'warning',
+				text: __(
+					'No blocks were changed. Review the selection or markup and try again.',
+					'superdav-ai-agent'
+				),
+			};

