const deferred = () => {
	let resolve;
	const promise = new Promise((r) => { resolve = r; });
	return { promise, resolve };
};

const queues = new Map();
const reflect = (id, event, work) => {
	const previous = queues.get(String(id));
	const reflection = previous
		? previous.catch(() => undefined).then(() => work(event))
		: work(event);
	queues.set(String(id), reflection);
	return reflection.finally(() => {
		if (queues.get(String(id)) === reflection) queues.delete(String(id));
	});
};

const first = deferred();
const applied = [];
const firstCall = reflect(7, 'first', () => first.promise);
const secondCall = reflect(7, 'second', async (event) => applied.push(event));

Promise.resolve().then(async () => {
	await Promise.resolve();
	console.log(JSON.stringify({
		firstSettled: false,
		secondStarted: applied.length > 0,
		queueRetained: queues.has('7'),
		secondBlocked: applied.length === 0,
	}));
	first.resolve();
	await firstCall;
	await secondCall;
	console.log(JSON.stringify({
		afterRelease: applied,
		queueCleared: !queues.has('7'),
	}));
});
