+	const ownerRef = useRef( Symbol( 'voice-conversation' ) );
+	const voiceTurnRef = useRef( false );
+	const [ pendingTranscript, setPendingTranscript ] = useState( null );
+	const [ phase, setPhase ] = useState( 'idle' );
